1: import type { Participante } from "@/lib/sorteo";
2: 
3: /** Regex de formato simple, suficiente para validar al ingreso. */
4: const REGEX_CORREO = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
5: 
6: export type ResultadoValidacion =
7:   | { participantes: Participante[] }
8:   | { error: string };
9: 
10: /**
11:  * Valida y normaliza el cuerpo de la solicitud de sorteo.
12:  *
13:  * Acepta `{ participantes: [{ nombre, correo }] }` y devuelve la lista
14:  * limpia (con los campos recortados), o un error descriptivo en español.
15:  * Los correos duplicados (sin distinguir mayúsculas/minúsculas) se rechazan.
16:  */
17: export function validarSolicitud(cuerpo: unknown): ResultadoValidacion {
18:   if (cuerpo === null || typeof cuerpo !== "object") {
19:     return { error: "Cuerpo de solicitud inválido." };
20:   }
21: 
22:   const { participantes } = cuerpo as { participantes?: unknown };
23:   if (!Array.isArray(participantes)) {
24:     return { error: "La lista de participantes es inválida." };
25:   }
26: 
27:   const limpios: Participante[] = [];
28:   const correosVistos = new Set<string>();
29: 
30:   for (const crudo of participantes) {
31:     if (crudo === null || typeof crudo !== "object") {
32:       return { error: "Hay un participante con datos inválidos." };
33:     }
34: 
35:     const nombre = String((crudo as { nombre?: unknown }).nombre ?? "").trim();
36:     const correo = String((crudo as { correo?: unknown }).correo ?? "").trim();
37: 
38:     if (nombre.length === 0) {
39:       return { error: "Todos los participantes deben tener un nombre." };
40:     }
41:     if (!REGEX_CORREO.test(correo)) {
42:       return { error: `El correo "${correo || "(vacío)"}" no es válido.` };
43:     }
44:     if (correosVistos.has(correo.toLowerCase())) {
45:       return { error: `El correo ${correo} está repetido.` };
46:     }
47: 
48:     correosVistos.add(correo.toLowerCase());
49:     limpios.push({ nombre, correo });
50:   }
51: 
52:   return { participantes: limpios };
53: }

