```ts
export function sortearAmigoSecreto(
  participantes: Participante[],
  opciones: OpcionesSorteo = {},
): ResultadoSorteo {
  const n = participantes.length;
  if (n < 2) return { ok: false, motivo: "Se requieren al menos 2 participantes para el sorteo." };

  const tipo = opciones.tipo ?? "individual";
  const K = tipo === "multiple" ? (opciones.cantidadAmigos ?? 0) : 1;
  if (!Number.isInteger(K) || K < 1 || K > n - 1) {
    return { ok: false, motivo: "La cantidad de amigos secretos no es válida." };
  }

  const permitida = construirMatrizPermitidas(participantes, opciones.exclusiones ?? []);
  const objetivo = n * K;
  const objetivo: targets per giver: number[][]
  if (!resolverConFlujo(permitida, K)) return { ok: false, motivo: "..." };

  const asignaciones = participantes.map((de, i) => objetivos[i].map(j => ({de, para: participantes[j]})));
  // Wait order: flatten by giver then slot. Insertion order: giver i, positions.
  aleatorizarObjetivos(objetivos, permitida);
  return asignaciones;
}
```

