function construirMatrizPermitidas(participantes, exclusiones): boolean[][] {
  const indice = new Map(participantes.map((p, i) => [p.correo.toLowerCase(), i] as const));
  const n = participantes.length;
  const excluida = new Set<string>();
  for (const { correo1, correo2 } of exclusiones) {
    const i = indice.get(correo1.toLowerCase());
    const j = indice.get(correo2.toLowerCase());
    if (i === undefined || j === undefined || i === j) continue; // la validación los rechaza antes
    excluida.add(`${i}-${j}`);
    excluida.add(`${j}-${i}`);
  }
  return Array.from({length: n}, (_, i) => Array.from({length: n}, (_, j) => i !== j && !excluida.has(`${i}-${j}`)));
}
```

