function resolverConFlujo(permitidas, K): number[][] | null {
  const n = permitidas.length;
  const totalNodos = 2 * n + 2;
  const s = 2 * n;
  const t = 2 * n + 1;
  const aristas: Arista[] = [];
  const adyacentes: number[][] = Array.from({length: totalNodos}, () => []);

  function crearArista(origen: number, destino: number, capacidad: number): void {
    const indice = aristas.length;
    aristas.push({ destino, capacidad, flujo: 0 });
    adyacentes[origen].push(indice);
    aristas.push({ destino: origen, capacidad: 0, flujo: 0 });
    adyacentes[destino].push(indice + 1);
  }

  for (let i = 0; i < n; i++) {
    crearArista(s, i, K);
    crearArista(n + i, t, K);
    for (let j = 0; j < n; j++) {
      if (permitidas[i][j]) crearArista(i, n + j, 1);
    }
  }

  // Edmonds–Karp en orden aleatorio de nodos: ... BFS
  const objetivo = n * K;
  let flujoTotal = 0;
  while (flujoTotal < objetivo) {
    const camino = buscarCamino(s, t, adyacentes, aristas, totalNodos);
    if (!camino) break;
    // aumentar
    let cuello = Infinity...
    ...
  }
  if (flujoTotal < objetivo) return null;
  // reconstruir targets
  const objetivos: number[][] = Array.from({length:n}, () => []);
  for (let i = 0; i < n; i++) {
    for (const idx of adyacentes[i]) {
      const a = aristas[idx];
      if (a.capacidad === 1 && a.flujo === 1) objetivos[i].push(a.destino - n);
    }
  }
  return objetivos;
}
```

