function buscarCamino(origen, destino, adyacentes, aristas, totalNodos): { anteriorArista: number[] } | null {
  const visitado = new Uint8Array(totalNodos);
  visitado[origen] = 1;
  const anteriorArista = new Int32Array(totalNodos).fill(-1);
  const pila = [origen];
  const vecinos: number[] = [];
  while (pila.length > 0) {
    const u = pila[pila.length - 1];
    if (u === destino) break;
    // vecinos aleatorios
    vecinos.length = 0;
    for (const idx of adyacentes[u]) {
      const v = aristas[idx].destino;
      if (!visitado[v] && aristas[idx].capacidad - aristas[idx].flujo > 0) vecinos.push(idx);
    }
    if (vecinos.length === 0) { pila.pop(); continue; }
    const idxElegido = vecinos[Math.floor(Math.random() * vecinos.length)];
    // marcar y avanzar; retroceso al agotar vecinos (si choose siempre avanza y marca, no revisita)
    ...
  }
}
