```ts
function aumentar(caminoIdx: number[], aristas: Arista[]) {
  const cuello = Math.min(...caminoIdx.map(idx => aristas[idx].capacidad - aristas[idx].flujo));
  for (const idx of caminoIdx) {
    aristas[idx].flujo += cuello;
    aristas[aristas[idx].inversa].flujo -= cuello; // residual inverso flujo positivo nunca; flujo del inverso decrece
  }
}
