export async function enviarAsignaciones(asignaciones: Asignacion[], opciones: OpcionesCorreo = {}): Promise<number> {
  const cliente = obtenerTransporte();
  const montoSugerido = opciones.montoSugerido;
  const conDestinos = agruparPorGiver(asignaciones); // Map correo → ; preserve insertion order
  let enviados = 0;
  for (const agrupado of conDestinos) {
    await cliente.sendMail(construirCorreo(agrupado, montoSugerido));
    enviados++;
  }
  return enviados;
}

function agruparPorGiver(asignaciones): Array<{ de: Participante; para: Participante[] }> {
  const orden: Array<{ de: Participante; para: Participante[] }> = [];
  const indice = new Map<string, { de: Participante; para: Participante[] }>();
  for (const asignacion of asignaciones) {
    const clave = asignacion.de.correo.toLowerCase();
    let grupo = indice.get(clave);
    if (!grupo) {
      grupo = { de: asignacion.de, para: [] };
      indice.set(clave, grupo);
      orden.push(grupo);
    }
    grupo.para.push(asignacion.para);
  }
  return orden;
}
