/**
 * Algoritmo de sorteo para el amigo secreto.
 *
 * Genera asignaciones aleatorias donde:
 * - Nadie se asigna a sí mismo (derangement).
 * - Todos regalan y reciben exactamente K veces (K = 1 en el modo individual).
 * - Nadie repite pareja: con K amigos secretos, a nadie le toca dos veces el mismo.
 * - Se respetan las exclusiones (pares de personas que no pueden tocarse).
 *
 * La existencia de un reparto válido se comprueba con un flujo máximo en la red
 * bipartita emisor → receptor con capacidad 1 por arista y capacidad K por nodo,
 * de modo que el "imposible" se detecta con certeza en vez de re-mezclar al azar.
 */

export interface Participante { nombre, correo }
export interface Asignacion { de, para }
export interface Exclusion { correo1: correo2: string }
export interface RangoMonto { minimo: number; maximo?: number }
export interface OpcionesSorteo {
  tipo?: "individual" | "multiple";
  cantidadAmigos?: number;
  montoSugerido?: RangoMonto;
  exclusiones?: Exclusion[];
}
export type ResultadoSorteo =
  | { ok: true; asignaciones: Asignacion[] }
  | { ok: false; motivo: string };
