{"content": "import { describe, expect, it } from "vitest";
import { sortearAmigoSecreto, type Participante } from "@/lib/sorteo";

function preparar(n: number): Participante[] {
  return Array.from({ length: n }, (_, i) => ({
    nombre: `Persona ${i + 1}`,
    correo: `persona${i + 1}@ejemplo.com`,
  }));
}

/** Stress temporal: se elimina tras la verificación. */
describe("estrés del algoritmo (temporal)", () => {
  it("n=60, K=5, varias cadenas de exclusiones abre en 200 sorteos", () => {
    const participantes = preparar(60);
    const exclusiones = Array.from({ length: 10 }, (_, i) => ({
      correo1: `persona${i + 1}@ejemplo.com`,
      correo2: `persona${((i + 1) % 60) + 1}@ejemplo.com`,
    }));

    for (let i = 0; i < 200; i++) {
      const resultado = sortearAmigoSecreto(participantes, {
        tipo: "multiple",
        cantidadAmigos: 5,
        exclusiones,
      });
      expect(resultado.ok).toBe(true);
      if (!resultado.ok) continue;
      expect(resultado.asignaciones).toHaveLength(300);
      for (const { de, para } of resultado.asignaciones) {
        expect(de).not.toBe(para);
      }
    }
  });

  it("n=120, K=10 abre", () => {
    const participantes = preparar(120);
    const inicio = Date.now();
    const resultado = sortearAmigoSecreto(participantes, {
      tipo: "multiple",
      cantidadAmigos: 10,
    });
    const duracion = Date.now() - inicio;
    expect(resultado.ok).toBe(true);
    expect(duracion).toBeLessThan(2000);
  });
});
